"""Feedback-controlled continuation; does not reset the simulation."""

import inspect
import math


class _Finished(Exception):
    pass


def _method(api, names):
    for name in names:
        value = getattr(api, name, None)
        if callable(value):
            return value
    return None


def _decode_pose(value):
    """Accept common Cartesian pose representations; yaw is optional."""
    if isinstance(value, dict):
        yaw = value.get("yaw_deg", value.get("yaw"))
        if all(k in value for k in ("x", "y", "z")):
            return [float(value[k]) for k in ("x", "y", "z")], yaw
        for key in ("tcp_pose", "tcp", "position", "pose"):
            if key in value:
                position, nested_yaw = _decode_pose(value[key])
                return position, yaw if yaw is not None else nested_yaw
    if hasattr(value, "tolist"):
        value = value.tolist()
    if isinstance(value, (list, tuple)):
        if len(value) == 2 and isinstance(value[0], (list, tuple)):
            return list(map(float, value[0][:3])), float(value[1])
        if len(value) in (3, 4) and all(
            isinstance(v, (int, float)) for v in value
        ):
            return list(map(float, value[:3])), (
                float(value[3]) if len(value) == 4 else None
            )
    raise RuntimeError("Cannot decode measured TCP pose without its API convention.")


