    Adapt explicitly named Cartesian interfaces, not joint-space interfaces.
    Unknown/ambiguous interfaces fail before issuing motion.
    """

    def __init__(self, api):
        self.api = api
        self.read = _method(
            api,
            ("get_tcp_pose", "tcp_pose", "get_tcp", "get_pose",
             "pose", "get_state", "state"),
        )
        if self.read is None:
            raise RuntimeError("Measured Cartesian TCP feedback is required.")

        self.force_read = _method(
            api, ("get_wrench", "read_wrench", "wrench",
                  "get_force", "get_forces", "force")
        )
        self.p, self.yaw = _decode_pose(self.read())
        self.move = None

        for name in ("move_tcp", "move_to", "move_cartesian", "move"):
            candidate = getattr(api, name, None)
            if not callable(candidate):
                continue
            try:
                parameters = inspect.signature(candidate).parameters
            except (TypeError, ValueError):
                continue

            names = set(parameters)
            relative = {"dx", "dy", "dz"} <= names
            absolute = {"x", "y", "z"} <= names
            vector = next(
                (k for k in ("position", "target_position", "xyz")
                 if k in names), None
            )
            yaw_key = next(
                (k for k in (
                    "dyaw_deg", "dyaw", "yaw_deg", "yaw",
                    "yaw_rad", "dyaw_rad"
                ) if k in names), None
            )
            if not (relative or absolute or vector) or yaw_key is None:
                continue

            supported = {
                "x", "y", "z", "dx", "dy", "dz",
                "position", "target_position", "xyz",
                yaw_key, "speed", "velocity", "acceleration",
                "force_limit", "max_force", "wait", "blocking",
            }
            required_unknown = [
                k for k, p in parameters.items()
                if p.default is inspect.Parameter.empty
                and p.kind not in (
                    inspect.Parameter.VAR_POSITIONAL,
                    inspect.Parameter.VAR_KEYWORD,
                )
                and k not in supported
            ]
            positional_only = any(
                p.kind == inspect.Parameter.POSITIONAL_ONLY
                for p in parameters.values()
            )
            if required_unknown or positional_only:
                continue

            self.move = candidate
            self.parameters = names
            self.relative = relative
            self.vector = vector if not (relative or absolute) else None
            self.yaw_key = yaw_key
            self.radians = (
                yaw_key.endswith("_rad")
                or "radian" in (inspect.getdoc(candidate) or "").lower()
            )
            break

        if self.move is None:
            raise RuntimeError(
                "Need a documented Cartesian motion method with XYZ and yaw; "
                "refusing to guess a joint/pose-vector convention."
            )

        if self.yaw_key.startswith("d") and self.yaw is None:
            raise RuntimeError("Relative yaw commands require measured initial yaw.")

        if self.radians and self.yaw is not None:
            self.yaw = math.degrees(self.yaw)
        self.baseline = self.wrench()

    def wrench(self):
        if self.force_read is None:
            return None
        value = self.force_read()
        if isinstance(value, dict):
            value = value.get(
                "force", value.get("forces", value.get("wrench"))
            )
        if hasattr(value, "tolist"):
            value = value.tolist()
        if isinstance(value, (int, float)):
            return [float(value)]
        if isinstance(value, (list, tuple)):
            if value and isinstance(value[0], (list, tuple)):
                value = value[0]
            return list(map(float, value[:3]))
        raise RuntimeError("Unrecognized force feedback representation.")

    def load(self):
        current = self.wrench()
        if current is None:
            return 0.0
        if self.baseline is None or len(current) != len(self.baseline):
            raise RuntimeError("Inconsistent force feedback.")
        return math.sqrt(sum(
            (a - b) ** 2 for a, b in zip(current, self.baseline)
        ))

    def go(self, x, y, z, yaw, speed=0.01):
        kwargs = {}
        if self.relative:
            kwargs.update(dx=x - self.p[0],
                          dy=y - self.p[1],
                          dz=z - self.p[2])
        elif self.vector:
            kwargs[self.vector] = [x, y, z]
        else:
            kwargs.update(x=x, y=y, z=z)

        angle = yaw
        if self.yaw_key.startswith("d"):
            angle = (yaw - self.yaw + 180.0) % 360.0 - 180.0
        kwargs[self.yaw_key] = math.radians(angle) if self.radians else angle

        for key, value in (
            ("speed", speed), ("velocity", speed),
            ("acceleration", 0.05),
            ("force_limit", 8.0), ("max_force", 8.0),
            ("wait", True), ("blocking", True),
        ):
            if key in self.parameters:
                kwargs[key] = value

        self.move(**kwargs)
        self.p, measured_yaw = _decode_pose(self.read())
        if measured_yaw is not None:
            self.yaw = (
                math.degrees(measured_yaw) if self.radians else measured_yaw
            )
        elif self.yaw_key.startswith("d"):
            raise RuntimeError("Lost yaw feedback during relative-yaw control.")

        if self.api.done():
            raise _Finished()
        return self.p

    def vertical(self, z, yaw, step=0.00025):
        """Guarded descent. Return False on contact or blocked motion."""
        x, y = self.p[:2]
        while self.p[2] > z + 0.00002:
            previous_z = self.p[2]
            target = max(z, previous_z - step)
            self.go(x, y, target, yaw, speed=0.002)
            if self.load() >= 3.0:
                return False
            requested = previous_z - target
            achieved = previous_z - self.p[2]
            if achieved < max(0.00002, 0.25 * requested):
                return False
            if abs(self.p[0] - x) > 0.0002 or abs(self.p[1] - y) > 0.0002:
                return False
        return True


