            yaw_candidates += [vyaw + 2.0 * i for i in range(1, 45)]

        for yaw in yaw_candidates:
            motion.retract(0.18)
            motion.rotate(yaw)
            motion.move_clear((seed[0], seed[1], 0.18))
            motion.move_clear((seed[0], seed[1], hover_z))

            # At <=1 degree yaw mismatch, a 0.4 mm XY lattice is fine enough
            # for the nominal square clearance, absent positioning errors.
            # Every attempt is unloaded before any lateral movement.
            for x, y in _spiral_grid(*seed, spacing=0.0004):
                motion.retract(hover_z)
                motion.move_clear((x, y, hover_z))

                if motion.descend(surface_z - 0.001):
                    # An opening, missing block, or partial entry is not yet
                    # success. Continue axially and let the simulator decide.
                    motion.descend(seating_z)
                    motion.done()

                motion.retract(hover_z)

        raise _Stop("Search exhausted without confirmed seating")

    except _Finished:
        return {"success": True}

    except (_Stop, ValueError, TypeError) as exc:
        # Leave an unsuccessful trial withdrawn, rather than forcing insertion.
        if motion is not None:
            try:
                motion.retract(0.18, emergency=True)
            except _Finished:
                return {"success": True}
            except Exception:
                pass
        return {
            "success": False,
            "reason": str(exc),
            "commands": 0 if motion is None else motion.count,
        }
