"""Feedback-controlled continuation; does not reset the cell."""

import inspect
import math
import statistics


SURFACE_Z = 0.05
CLEARANCE_Z = 0.1672
MIN_TCP_Z = 0.019
SEARCH_STEP = 0.0005
DESCENT_STEP = 0.0005
AXIAL_LIMIT = 6.0
LATERAL_LIMIT = 4.0

# These observations are evidence, not a reason to clamp the estimate to the
# advertised placement interval. Their discrepancy warrants a fallback search.
PREVIOUS_XY = [
    (0.555009546, -0.138567849),
    (0.555739408, -0.134403543),
    (0.553191848, -0.132084452),
    (0.550702430, -0.135645216),
