    (0.554367230, -0.137337751),
    (0.550865459, -0.133286895),
    (0.552483399, -0.137022369),
]
PREVIOUS_YAW = [
    10.052629, 10.353795, 10.323268, 10.288303, 10.153386,
    10.219840, 10.382200, 10.217459, 10.215500, 10.702868,
    10.351135, 10.517409, 9.858724,
]


def _reader(api, names):
    for name in names:
        if hasattr(api, name):
            def read(name=name):
                value = getattr(api, name)
                return value() if callable(value) else value
            return read
    raise RuntimeError("Required feedback unavailable: " + ", ".join(names))


def _xyz(value):
    if isinstance(value, dict):
        if all(k in value for k in ("x", "y", "z")):
            return tuple(float(value[k]) for k in ("x", "y", "z"))
        for key in ("tcp", "tcp_pose", "position", "pose", "xyz"):
            if key in value:
                return _xyz(value[key])
    if hasattr(value, "position"):
        return _xyz(value.position)
    if all(hasattr(value, k) for k in ("x", "y", "z")):
        return (float(value.x), float(value.y), float(value.z))
    try:
        if len(value) and hasattr(value[0], "__len__"):
            return _xyz(value[0])
        return tuple(float(value[i]) for i in range(3))
    except (TypeError, ValueError, IndexError):
        raise RuntimeError("Cannot decode measured TCP position")


def _force(value):
    if isinstance(value, dict):
        if all(k in value for k in ("fx", "fy", "fz")):
            return tuple(float(value[k]) for k in ("fx", "fy", "fz"))
        for key in ("force", "forces", "wrench", "ft"):
            if key in value:
                return _force(value[key])
    if hasattr(value, "force"):
        return _force(value.force)
    if isinstance(value, (int, float)):
        return (0.0, 0.0, float(value))
    return _xyz(value)


class Controller:
    """
    Small interface adapter. Only explicitly recognizable motion signatures are
    used; unsupported interfaces fail before an experimental motion is issued.
    Generic yaw arguments use the degrees returned by hole_pose().
    """

    def __init__(self, api):
        self.api = api
        self.read_pose = _reader(
            api, ("get_tcp_pose", "tcp_pose", "get_pose",
                  "get_position", "get_state", "tcp")
        )
        self.read_force = _reader(
            api, ("get_wrench", "get_tcp_force", "get_force",
                  "get_forces", "force_torque", "wrench", "force")
        )
        self.motion = None
        self.yaw = None
        self.baseline = (0.0, 0.0, 0.0)

        for name in ("move_to", "move_tcp", "move", "move_relative", "move_delta"):
            fn = getattr(api, name, None)
            if not callable(fn):
                continue
            try:
                params = inspect.signature(fn).parameters
            except (ValueError, TypeError):
                continue

            names = set(params)
            if {"dx", "dy", "dz"} <= names:
                mode = "relative"
                recognized = {"dx", "dy", "dz"}
            elif {"x", "y", "z"} <= names:
                mode = "absolute"
                recognized = {"x", "y", "z"}
            else:
                vectors = names & {"position", "xyz", "target_xyz"}
                if len(vectors) != 1:
                    continue
                mode = next(iter(vectors))
                recognized = {mode}

            recognized |= {
                "yaw", "yaw_deg", "yaw_rad", "dyaw", "dyaw_deg",
                "speed", "velocity", "max_force", "force_limit",
                "blocking", "wait",
            }
            if any(
                p.default is inspect.Parameter.empty
                and p.kind not in (
                    inspect.Parameter.VAR_POSITIONAL,
                    inspect.Parameter.VAR_KEYWORD,
                )
                and key not in recognized
                for key, p in params.items()
            ):
                continue
            if any(p.kind == inspect.Parameter.POSITIONAL_ONLY
                   for p in params.values()):
                continue
            if not names & {"yaw", "yaw_deg", "yaw_rad", "dyaw", "dyaw_deg"}:
                continue

            self.motion = (fn, names, mode)
            break

        if self.motion is None:
            raise RuntimeError(
                "No supported, yaw-controllable Cartesian motion interface"
            )

        # Verify feedback decoding before moving.
        self.position()
        _force(self.read_force())

    def position(self):
        return _xyz(self.read_pose())

    def tare(self):
        samples = [_force(self.read_force()) for _ in range(5)]
        self.baseline = tuple(
            statistics.median(s[i] for s in samples) for i in range(3)
        )

    def load(self):
        f = _force(self.read_force())
        return tuple(f[i] - self.baseline[i] for i in range(3))

    def contact(self):
        fx, fy, fz = self.load()
        return math.hypot(fx, fy) >= LATERAL_LIMIT or abs(fz) >= AXIAL_LIMIT

    def _measured_yaw(self):
        raw = self.read_pose()
        if isinstance(raw, dict):
            if "yaw_deg" in raw:
                return float(raw["yaw_deg"])
            if "yaw" in raw:
                return float(raw["yaw"])
        try:
            if len(raw) == 2 and hasattr(raw[0], "__len__"):
                return float(raw[1])
            if len(raw) == 4:
                return float(raw[3])
        except (TypeError, ValueError):
            pass
        raise RuntimeError(
            "Relative yaw motion requires measured yaw in degrees"
        )

    def move(self, x, y, z, yaw, speed):
        fn, names, mode = self.motion
        kw = {}
        if mode == "relative":
            old = self.position()
            kw.update(dx=x - old[0], dy=y - old[1], dz=z - old[2])
        elif mode == "absolute":
            kw.update(x=x, y=y, z=z)
        else:
            kw[mode] = [x, y, z]

        if "yaw_deg" in names:
            kw["yaw_deg"] = yaw
        elif "yaw_rad" in names:
            kw["yaw_rad"] = math.radians(yaw)
        elif "yaw" in names:
            kw["yaw"] = yaw
        else:
            current_yaw = self._measured_yaw()
            delta = (yaw - current_yaw + 180.0) % 360.0 - 180.0
            kw["dyaw_deg" if "dyaw_deg" in names else "dyaw"] = delta

        for key in ("speed", "velocity"):
            if key in names:
                kw[key] = speed
        for key in ("max_force", "force_limit"):
            if key in names:
                kw[key] = AXIAL_LIMIT
        for key in ("blocking", "wait"):
            if key in names:
                kw[key] = True

        fn(**kw)
        self.yaw = yaw

    def retract(self, yaw):
        x, y, z = self.position()
        self.move(x, y, max(z, CLEARANCE_Z), yaw, 0.01)
        if self.position()[2] < CLEARANCE_Z - 0.001:
            raise RuntimeError("Retraction obstructed; stopping rather than dragging")


def _square_spiral(radius):
    yield 0, 0
    for r in range(1, radius + 1):
        for i in range(-r, r):
            yield i, -r
        for j in range(-r, r):
            yield r, j
        for i in range(r, -r, -1):
            yield i, r
        for j in range(r, -r, -1):
            yield -r, j


def run(api):
    if api.done():
        return

    ctrl = Controller(api)

    xy = list(PREVIOUS_XY)
    angles = list(PREVIOUS_YAW)
    for _ in range(12):
        position, angle = api.hole_pose()
        x, y = float(position[0]), float(position[1])
        angle = float(angle)
        if all(math.isfinite(v) for v in (x, y, angle)):
            xy.append((x, y))
            angles.append(angle)

    cx = statistics.mean(p[0] for p in xy)
    cy = statistics.mean(p[1] for p in xy)
    yaw = statistics.median(angles)

    # Keep the existing downward tool tilt. Establish a gravity/holding-force
    # reference only in free space, never while pressing on the block.
    initial = ctrl.position()
    if initial[2] < CLEARANCE_Z - 0.001:
        # The supplied continuation state should not take this branch.
        raise RuntimeError("Unexpected low starting TCP; cannot safely tare")
    ctrl.tare()
    if ctrl.contact():
        raise RuntimeError("Unstable free-space force reading")

    # Rotate only at clearance, then re-tare for the selected yaw.
    ctrl.move(initial[0], initial[1], CLEARANCE_Z, yaw, 0.01)
    ctrl.tare()

    def probe(x, y, angle):
        """Retract between trials; never perform a lateral search under load."""
        if api.done():
            return True

        ctrl.retract(ctrl.yaw)
        ctrl.move(x, y, CLEARANCE_Z, angle, 0.02)
        measured = ctrl.position()
        if math.hypot(measured[0] - x, measured[1] - y) > 0.001:
            raise RuntimeError("Lateral target not reached")
        if ctrl.contact():
            ctrl.retract(angle)
            raise RuntimeError("Unexpected contact at travel height")
        ctrl.tare()

        # An 80 mm downward peg is clear here whether TCP denotes its tip or
        # its upper end. Subsequent descent uses measured position and force,
        # not an assumed 80 mm TCP-to-tip transform.
        entry_z = SURFACE_Z + 0.080 + 0.004
        ctrl.move(x, y, entry_z, angle, 0.005)
        if api.done():
            return True
        if ctrl.contact():
            ctrl.retract(angle)
            return False

        for _ in range(300):
            before = ctrl.position()
            if before[2] <= MIN_TCP_Z:
                break
            if ctrl.contact():
                break

            target_z = max(MIN_TCP_Z, before[2] - DESCENT_STEP)
            ctrl.move(x, y, target_z, angle, 0.002)

            # The simulator, not commanded depth, determines seating.
            if api.done():
                return True

            after = ctrl.position()
            if ctrl.contact():
                break
            if after[2] > before[2] - 0.0001:
                break  # Stalled motion: do not accumulate downward commands.
            if math.hypot(after[0] - x, after[1] - y) > 0.0008:
                break

        ctrl.retract(angle)
        return False

    # First test the coherent measured location. Averaging reduces random
    # measurement noise; the fine grid handles remaining sub-mm uncertainty.
    # Rotate the grid with the square hole.
    c, s = math.cos(math.radians(yaw)), math.sin(math.radians(yaw))
    for i, j in _square_spiral(12):
        dx, dy = i * SEARCH_STEP, j * SEARCH_STEP
        if probe(cx + c * dx - s * dy, cy + s * dx + c * dy, yaw):
            return

    # Small angular corrections are attempted only after retracting.
    for offset in (-2.0, 2.0):
        for i, j in _square_spiral(6):
            dx, dy = i * SEARCH_STEP, j * SEARCH_STEP
            if probe(cx + c * dx - s * dy,
                     cy + s * dx + c * dy, yaw + offset):
                return

    # The reported x/y lie outside the nominal placement box. If they were
    # systematically biased, search that box independently; do not merely
    # clamp the bad estimate to an edge. The fine spacing resolves the
    # 0.5 mm-per-side clearance at the measured yaw.
    for i, j in _square_spiral(100):
        x = 0.45 + i * SEARCH_STEP
        y = j * SEARCH_STEP
        if probe(x, y, yaw):
            return

    ctrl.retract(ctrl.yaw)
    raise RuntimeError(
        "Search exhausted without verified seating; peg retracted. "
        "Check hole-pose frame/calibration and tool yaw calibration."
    )
